                    // the `invokespecial` twin is in the `0xb7` arm).
                    if op == 0xb6
                        && code[pc] == 0xb6
                        && !first_call
                        && self.try_reference_refers_to_intrinsic(
                            pc, info_ptr, num_args, ret_type, code_len,
                        )
                    {
                        crate::ir_evidence::note_builder_expansion();
                        pc += ilen;
                        continue;
                    }
                    self.note_first_call(pc, info_ptr);
