                    // a linked capturing lambda site, as its proxy's `new`
                    // plus one store per capture.
                    if self.try_indy_capture_new(pc, arg_entries, ret_tag) {
                        crate::ir_evidence::note_builder_expansion();
                        pc += 5;
                        continue;
                    }
