    /// CH6W5-1: off, the unproven nested site stays the call (the round-13
    /// shape, `r13w10_a_nested_call_on_another_object_keeps_the_call`); on, it
    /// splices `g` behind `ExactClassIs(class 7)` and keeps that call as the
    /// miss edge, joined with the body's `5`.
    #[test]
    fn r19_a_nested_unproven_exact_site_takes_a_guarded_splice() {
        let off = nested_guarded_graph("0");
        assert!(!off
            .nodes
            .iter()
            .any(|n| matches!(n.op, Op::ExactClassIs { class_id: 7 })));
        let on = nested_guarded_graph("1");
        let tests = on
            .nodes
            .iter()
            .filter(|n| matches!(n.op, Op::ExactClassIs { class_id: 7 }))
            .count();
        assert_eq!(tests, 1, "one class test at the nested site");
        assert_eq!(
            on.nodes
                .iter()
                .filter(|n| matches!(n.op, Op::Call { .. }))
                .count(),
            off.nodes
                .iter()
                .filter(|n| matches!(n.op, Op::Call { .. }))
                .count(),
            "the miss edge is the same one call"
        );
        assert!(
            on.nodes.iter().any(|n| matches!(n.op, Op::Const(5))),
            "g's body"
        );
        assert!(
            on.nodes
                .iter()
                .any(|n| n.op == Op::Phi && n.ty == IrType::Int),
            "the result joins the body's value and the call's"
        );
    }

    /// JIT round 19 proposal wave 5 (lane mega5, MEGAOSR4-1): `NESTED_ARG`
