                let mut invoke_info = HashMap::new();
                invoke_info.insert(9usize, (m_info as *const JitInvokeInfo as usize, 2, b'I'));
                invoke_info.insert(15usize, (info, 1usize, b'I'));
                b.set_invoke_info(invoke_info);
